
let lasers = [];
let asteroids = [];

// ship respawns
let shipInvincible = false;
let shipInvincibleTime = 0;
const INVINCIBILITY_DURATION = 3000;

// asteroid respawn
let largeAsteroidTimer = 0;
const LARGE_RESPAWN_DELAY = 10000;

// spaceships variables
let shipImg, thrustImg, lazerImg;

// asteroids variables
let smallAsteroid, largeAsteroid, mediumAsteroid;

let ship1b64 = "data:image/png;base64,";
let thrust1b64 = "data:image/png;base64,";
let laser2b64 = "data:image/png;base64,";

// asteroids pictures
let lg_asteroidb64 = "data:image/png;base64,";
let md_asteroidb64 = "data:image/png;base64,";
let sm_asteroidb64 = "data:image/png;base64,";

function preload() {
  shipImg = loadImage(ship1b64);
  thrustImg = loadImage(thrust1b64);
  laserImg = loadImage(laser2b64);

  largeAsteroid = loadImage(lg_asteroidb64);
  mediumAsteroid = loadImage(md_asteroidb64);
  smallAsteroid = loadImage(sm_asteroidb64);
}



